INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/89978', 'unal/89978', 'Prototipo de asistente virtual como apoyo al proceso de aprendizaje en una asignatura de análisis y visualización de datos utilizando grandes modelos de lenguaje', '2026', 'maestria', 'Magíster en Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/89978', 'estudiante:olaya-castro-hendrik-eugenio', 'Olaya Castro, Hendrik Eugenio', '', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/89979', 'unal/89979', 'Sistema de asistencia virtual basado en LLMs para el manejo del cultivo de papa', '2026', 'maestria', 'Maestría en Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/89979', 'estudiante:cruz-chu-mariana-beatriz', 'Cruz Chú, Mariana Beatriz', 'Este trabajo final presentó el desarrollo y la evaluación de un sistema de asistencia virtual para consultas sobre el manejo del cultivo de papa, basado en grandes modelos de lenguaje con recuperación contextual. El trabajo se ejecutó en cuatro fases de acuerdo con los objetivos específicos. Primero, se estructuró una base de conocimiento a partir de publicaciones de acceso abierto sobre el cultivo de papa, mediante la recolección sistemática, el filtrado por criterios temáticos, geográficos y temporales, la extracción de texto y la normalización del contenido. Asimismo, se planteó una arquitectura modular que incorpora la recuperación semántica de fragmentos y un mecanismo de trazabilidad para identificar las fuentes utilizadas en cada respuesta a consultas en lenguaje natural. Luego, se implementó un prototipo que presentó los identificadores de los fragmentos recuperados como evidencia documental. Finalmente, el prototipo se evaluó mediante un enfoque de modelo de lenguaje como juez, aplicando un conjunto de consultas distribuidas por estratos temáticos y calificando las respuestas según su relevancia, exactitud, claridad, utilidad y evaluación global. Los resultados mostraron un desempeño consistente en claridad y variación entre estratos, con un menor rendimiento en las consultas asociadas a condiciones ambientales. Por último, se presentan evidencias de funcionamiento y de evaluación, y se listan limitaciones y líneas de trabajo futuras vinculadas a la cobertura documental, la validación con expertos y las mejoras en las estrategias de recuperación. (Texto tomado de la fuente)', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/89150', 'unal/89150', 'Análisis automatizado de comparación de productos con técnicas de procesamiento de lenguaje natural para artículos deportivos extraídos de canales de comercio electrónico', '2025', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/89150', 'estudiante:correa-lombana-juan-manuel', 'Correa Lombana, Juan Manuel', 'En el dinámico entorno del comercio electrónico, el análisis competitivo de productos es un pilar estratégico, aunque su ejecución manual es ineficiente y propensa a errores debido a la heterogeneidad de la información. Este trabajo aborda la automatización de la comparación de artículos deportivos, específicamente calzado de running, extrayendo datos de múltiples plataformas de e-commerce. La contribución principal es un pipeline que implementa un paradigma de "extracción primero, comparación después". Se utiliza un Modelo de Lenguaje Grande (LLM) para transformar descripciones de producto no estructuradas en un conjunto normalizado de atributos técnicos clave, definidos mediante un consenso de expertos con el método Delphi. Posteriormente, sobre estas representaciones estructuradas, se aplican técnicas de embeddings y el algoritmo K-Vecinos más Cercanos (KNN) para cuantificar la similitud funcional e identificar productos equivalentes. Los resultados demuestran una reducción del tiempo de análisis superior al 99.9% en comparación con el proceso manual y una alta validación cualitativa por parte de expertos (4.35 sobre 5.0), validando la herramienta como un recurso eficaz para la inteligencia de negocio, la optimización de precios y la toma de decisiones estratégicas en el sector retail (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/88357', 'unal/88357', 'Evaluación automática de casos de prueba de ejercicios de programación de computadores', '2025', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/88357', 'estudiante:rivera-cardenas-david-leonardo', 'Rivera Cárdenas, David Leonardo', 'El reciente crecimiento de plataformas de evaluación automática de ejercicios de programación de computadores ha ayudado a los docentes en la retroalimentación de las soluciones propuestas por los estudiantes; esto es un factor importante en el desarrollo de habilidades de programación de computadores. Sin embargo, los docentes enfrentan desafíos a la hora de conocer si los casos de prueba que han creado tienen la suficiente cobertura, la cual hace referencia a la cantidad o porcentaje de código que es alcanzado por las pruebas. El objetivo general del presente trabajo es proponer y desarrollar un prototipo funcional de una herramienta que mida, de manera automática, la calidad de un conjunto de casos de prueba usados para evaluar la solución de ejercicios de programación de computadores. La herramienta mide el nivel de cobertura de estos casos mediante métricas como cobertura de rama y línea, proporcionando información de su calidad. La metodología empleada incluyó una revisión de la literatura sobre técnicas, métricas y herramientas de evaluación de pruebas, seguida del diseño, implementación y validación del prototipo utilizando un conjunto de datos de soluciones y casos de prueba de 18 ejercicios del curso Introducción a la Programación en Python de la Universidad Nacional de Colombia. Los resultados muestran que la herramienta permite identificar deficiencias en la cobertura de los casos de prueba y, a partir de ellos, se sugieren oportunidades de mejora para fortalecer el proceso de creación de casos de prueba para la evaluación de ejercicios de programación. Este trabajo contribuye a la mejora continua de la enseñanza de programación de computadores, al ofrecer una solución automática para la evaluación de pruebas, que proporcione una orientación a los docentes para la generación de casos de prueba más completos y efectivos, por medio de la identificación del nivel de cobertura alcanzado. (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/89211', 'unal/89211', 'Modelo de predicción de abandono de clientes en un marketplace mediante técnicas de machine learning', '2025', 'maestria', 'Magíster en Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/89211', 'estudiante:baquero-pico-cristian-adolfo', 'Baquero Pico, Cristian Adolfo', 'En el contexto competitivo de los marketplaces, la retención de clientes se ha convertido en un factor estratégico clave. Este trabajo presenta el desarrollo de un modelo predictivo de abandono de clientes (churn) aplicando técnicas de aprendizaje automático (machine learning), con el objetivo de identificar proactivamente a aquellos usuarios con mayor probabilidad de abandonar la plataforma. El estudio se estructura bajo la metodología CRISP-DM, abordando desde la selección y análisis de una base de datos —“theLook eCommerce”— hasta la preparación de características y la comparación de múltiples algoritmos. Se evaluaron diferentes configuraciones temporales para representar el con texto del cliente, y se identificaron las más efectivas en términos de desempeño predictivo. El modelo desarrollado, basado en Random Forest, alcanzó métricas superiores al 82 % en Accuracy y 78 % en F1-score, demostrando su utilidad para apoyar estrategias de retención en entornos reales. Este trabajo reafirma la necesidad de enfoques personalizados en la predicción del churn y sienta las bases para su implementación práctica. (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/89227', 'unal/89227', 'Prototipo de plataforma educativa basada en modelos de lenguaje para el apoyo en el aprendizaje de matemáticas básicas', '2025', 'maestria', 'Magíster en Ingeniería de Sistemas', 'https://repositorio.unal.edu.co/handle/unal/89227', 'estudiante:pabon-correa-david-alejandro', 'Pabón Correa, David Alejandro', 'El presente trabajo desarrolla un prototipo de plataforma educativa de código abierto orientada a la enseñanza de matemáticas básicas, integrando modelos de lenguaje para ofrecer tutoría personalizada. La propuesta surge como respuesta a la brecha de aprendizaje matemático en Colombia y a la necesidad de contar con herramientas capaces de operar en entornos con recursos limitados. Se plantea la adaptación de modelos de lenguaje pequeños (Small Language Models) al dominio de las matemáticas elementales, con el propósito de generar explicaciones paso a paso y fomentar el aprendizaje activo. El documento describe las fases de diseño pedagógico, la construcción de un conjunto de datos en español, el ajuste fino de los modelos y la implementación de un prototipo con interfaz de usuario. Los resultados obtenidos muestran la factibilidad técnica y pedagógica de esta aproximación en escenarios de baja conectividad, y se plantea su potencial escalabilidad como alternativa inclusiva para fortalecer la enseñanza de las matemáticas en el sistema educativo colombiano (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/86557', 'unal/86557', 'Evaluación del efecto de un laboratorio híbrido en el aprendizaje de un Lenguaje de Descripción de Hardware (HDL)', '2024', 'maestria', 'Magíster en Ingeniería - Automatización Industrial', 'https://repositorio.unal.edu.co/handle/unal/86557', 'estudiante:rodriguez-pinto-father-alexander', 'Rodriguez Pinto, Father Alexander', 'Las iniciativas para mejorar el aprendizaje de los estudiantes han ido en aumento gracias a los avances en las telecomunicaciones y una mayor presencia de equipo de cómputo en los contextos educativos. Entre estas iniciativas se encuentran los laboratorios remotos que permiten la experimentación a distancia. En la misma línea se encuentran los laboratorios híbridos, que pueden agrupar tanto elementos remotos como virtuales o presenciales. El aprendizaje requiere que estas herramientas puedan ser efectivas a un alto nivel. De esta forma, pueden contribuir a motivar a los estudiantes para aprender y generar un flujo positivo en sus calificaciones y recompensas académicas. En electrónica digital, el aprendizaje de los lenguajes de descripción de hardware es de especial interés en el desarrollo de habilidades prácticas en la creación e implementación de circuitos electrónicos digitales. No obstante, se presentan desafíos para los estudiantes, docentes e instituciones. El aprendizaje requiere de estrategias, métodos y herramientas bien pensadas para atender y superar estos desafíos. Por esta razón, las iniciativas de laboratorios para atender a la parte práctica de una asignatura deben ser acompañadas por evidencia empírica para establecer las estrategias y formas de incorporar su funcionalidad en el contexto académico. La revisión de literatura presentó varias iniciativas de laboratorios remotos e híbridos, las cuales han sido generalmente bien recibidas por los estudiantes. En diversos casos, sus percepciones han permitido reconocer los beneficios y bondades que les han generado las nuevas iniciativas para la práctica de laboratorio. A pesar de ello, se encuentran pocos trabajos de validación de estas iniciativas desde el ámbito educativo. En otros casos, los instrumentos utilizados no están estandarizados o simplemente no han sido aplicados. En variables como la motivación por aprender, la evidencia acerca de iniciativas de laboratorios remotos es escasa y aún más para los de tipo híbrido. De esta manera, algunos autores enfatizan la necesidad de realizar más investigación involucrando distintas iniciativas de laboratorios, con el fin de encontrar sus efectos en diversas variables. Con la disponibilidad de mayor evidencia, se podrían tomar mejores decisiones acerca de los componentes de laboratorio práctico para asignaturas relacionadas con electrónica digital que involucren la práctica con un lenguaje de descripción de hardware. A partir de lo expuesto, este trabajo busca aportar evidencia acerca de los efectos en el rendimiento y la motivación en el aprendizaje de un HDL para una asignatura de electrónica digital. Para este propósito, se desplegó un laboratorio híbrido que reúne las modalidades remota y tradicional (Hands-On). El despliegue se realizó bajo una intervención educativa diseñada previamente como un estudio cuasi-experimental. Se trabajó con dos grupos, uno experimental y uno de control. En este proceso, se escogió un laboratorio remoto que, junto a la modalidad tradicional usualmente manejada, se constituyó como un laboratorio híbrido destinado a ser implementado en el grupo experimental. Mientras tanto, el grupo control se mantuvo bajo la modalidad tradicional. Se caracterizó la motivación por aprender gracias a la aplicación de cuestionarios del MSLQ-Colombia, al inicio y al final de la experiencia. Además, se llevó a cabo una encuesta de percepción y se recolectaron las notas de los informes de laboratorio entregados por los estudiantes. Estas acciones de recolección permitieron extraer datos acerca de la motivación y el rendimiento, así como las opiniones y percepciones acerca de la experiencia y las herramientas en detalle. El análisis de la información recolectada se llevó a cabo usando métodos estadísticos para verificar las variaciones en la motivación y el rendimiento. Los datos cuantitativos no arrojaron efectos significativamente positivos en la motivación o el rendimiento. El enfoque cualitativo permitió encontrar hallazgos importantes a partir de la percepción de los estudiantes. Se reportaron beneficios para el trabajo autónomo, buenas expectativas de rendimiento y disminución en niveles de ansiedad gracias a una mejor confianza en la experimentación del laboratorio. Estas son evidencias que pueden ser valoradas de forma positiva para establecer nuevas iniciativas de laboratorios híbridos que apunten al aprendizaje efectivo de lenguajes de descripción de hardware (HDL). (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/84828', 'unal/84828', 'Análisis automático de código fuente aplicado en el software para comercio en línea: SAP Commerce Cloud', '2023', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/84828', 'estudiante:ramirez-espejo-roger-steven', 'Ramírez Espejo, Roger Steven', 'Este documento plantea un trabajo final de maestría para apoyar el proceso de migración de SAP Commerce a la nube pública de Microsoft Azure. Se destaca la importancia de la analítica de software y el análisis automático de código fuente para obtener datos concretos que respalden las decisiones de arquitectura, diseño y desarrollo. SAP Commerce Cloud, un producto utilizado para implementaciones de comercio en línea, presenta desafíos al ajustar y extender sus funcionalidades según las necesidades de cada cliente. Además, se menciona la falta de una herramienta automatizada que facilite la migración de SAP Commerce a la nube pública. En este contexto, se propone una estrategia que utiliza la herramienta de análisis de código fuente PMD para respaldar las migraciones a la arquitectura en la nube, y se evalúa su rendimiento a través de estudios de caso. (Texto tomado de la fuente)', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/85634', 'unal/85634', 'Development of a software method to assist in the thematic analysis of responses to open ended questions in Spanish-language surveys', '2023', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/85634', 'estudiante:canas-palomino-luis-alfonso', 'Cañas Palomino, Luis Alfonso', 'Thematic analysis is fundamental in qualitative research, providing rich insights but often requiring substantial time and expertise. This work addresses some limitations of existing Computer-Assisted Qualitative Data Analysis Software (CAQDAS) and presents a novel method specifically designed to assist in the thematic analysis of multi-label open-ended questions in Spanish-language surveys. The proposed method melds domain expertise with advanced language models to establish preliminary categories. Subsequently, human discernment is combined with similarity measures to streamline the categorization of some responses using these preliminary categories. The process culminates in a robust and scalable automated categorization, utilizing diverse models, language models, and accuracy metrics. The proposed method is composed of three modular phases that can function independently or collaboratively, offering a comprehensive solution for researchers. It can reduce the labor-intensive coding process by leveraging Large Language Models (LLMs) and Natural Language Processing (NLP) techniques. The method''s efficacy is evaluated through its application on a dataset from the National University of Colombia, demonstrating promising results across its various modules and pathways. The work opens avenues for further research, particularly in enhancing qualitative analysis methods with the integration of modern tools. (Texto tomado de la fuente)', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/83931', 'unal/83931', 'Prototipo de una herramienta de software de calificación automática con proceso de realimentación para el apoyo al aprendizaje de lenguajes de descripción de hardware', '2023', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/83931', 'estudiante:corso-pinzon-andres-francisco-jose', 'Corso Pinzón, Andrés Francisco José', 'Los lenguajes de descripción de hardware se han popularizado en el diseño de electrónica digital debido al aumento de la complejidad de los circuitos actuales. Debido a lo anterior, se hace necesario apoyar el proceso de aprendizaje de electrónica digital utilizando estos lenguajes. El objetivo principal de este trabajo es desarrollar un prototipo de una herramienta de software de calificación automática con proceso de realimentación para el apoyo al aprendizaje de Lenguajes de Descripción de Hardware. Para lograrlo, este trabajo presenta la selección de características que debería incluir el prototipo, basado en otras herramientas similares. Posteriormente se realizó el diseño e implementación de un prototipo que fue usado por estudiantes del curso de Electrónica Digital de la Universidad Nacional de Colombia por cinco (5) semanas. Con este estudio se obtuvieron las percepciones de su uso. Los estudiantes encontraron útil para el proceso de aprendizaje tener una herramienta de calificación automática con realimentación, pues al estar disponible en línea da una ventaja al no depender de un profesor o tutor. (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/83049', 'unal/83049', 'Analítica de aprendizaje en la asignatura Programación de Computadores: una investigación basada en métodos mixtos', '2022', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/83049', 'estudiante:chaparro-amaya-edna-johanna', 'Chaparro Amaya, Edna Johanna', 'El reciente crecimiento de nuevas formas de datos educativos, ha hecho que la analítica del aprendizaje surja como una solución para identificar información relevante en la toma de decisiones educativas. Un grupo de investigaciones en analítica del aprendizaje se concentra en identificar variables del proceso de aprendizaje relacionadas con el desempeño académico de los estudiantes. Sin embargo, pocas investigaciones consideran el uso de metodologías mixtas o cualitativas, lo que limita el entendimiento sobre los comportamientos de los alumnos. El objetivo general de este trabajo es determinar las relaciones existentes entre las medidas y métricas derivadas del proceso de aprendizaje y el rendimiento académico de los estudiantes en la asignatura Programación de Computadores de la Facultad de Ingeniería en la Universidad Nacional de Colombia durante 2019 y 2020. Este trabajo propone un diseño metodológico con enfoque mixto, no experimental, donde la fase cualitativa de la metodología está enfocada hacia el análisis de contenido. Los resultados evidencian que existe una correlación positiva entre la cantidad de intentos de solución realizados por el alumno y su desempeño académico, lo que posiblemente se puede asociar a las percepciones de los estudiantes sobre la plataforma educativa utilizada en el curso como un ambiente que promueve la práctica constante debido a su disponibilidad en línea. Los errores/veredictos de las soluciones enviadas (respuesta correctas e incorrecta, límite de memoria excedido, errores de compilación y límite de tiempo excedido) también tienen correlaciones positivas, las cuales son corroboradas con las referencias de los estudiantes sobre retroalimentación formativa, consejos orientativos y casos de prueba. Métricas de software como el conteo de tokens y las líneas de código de los programas diseñados por los estudiantes tienen una correlación positiva significativa con la calificación final del alumno, lo cual se puede vincular con las referencias sobre ejercicios estimulantes y motivantes dentro de la plataforma educativa. Por otra parte, el índice de mantenibilidad tiene una correlación negativa, lo que se puede relacionar con las opiniones que resaltan la obtención de habilidades de programación. En contraste, se observan correlaciones negativas entre el uso de las herramientas de la plataforma educativa utilizada en el curso (p. ej. pruebas personalizadas, visualización de la ejecución del código y verificación de buenas prácticas de programación) con el rendimiento académico, las cuales son refutadas con las referencias de los estudiantes a estas herramientas como elementos positivos de la plataforma. En conclusión, se evidencia como el uso de métodos mixtos permite que los hallazgos de la fase cuantitativa sean corroborados, complementados o refutados por medio de las observaciones de los datos cualitativos. (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/82923', 'unal/82923', 'Evaluación del impacto en la motivación en el aprendizaje de los estudiantes de programación de computadores mediante el uso de una herramienta de evaluación automática', '2022', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/82923', 'estudiante:lozano-rojas-hernan-dario', 'Lozano Rojas, Hernan Dario', 'La enseñanza y aprendizaje en el contexto educativo ha requerido a través del tiempo de diferentes esfuerzos por parte de los estudiantes y de los docentes para que se pueda dar un proceso satisfactorio en el que se cumpla con el objetivo de garantizar un completo aprendizaje. En el aprendizaje de la programación de computadores los estudiantes se enfrentan a distintos retos, por lo que el rol del docente, en su constante búsqueda y actualización, opta por incluir estrategias innovadoras mediante el apoyo de tecnologías computacionales con el fin de facilitar la apropiación del conocimiento por parte del estudiante. Cada vez hay más estrategias educativas que integran herramientas tecnológicas de evaluación automática de tipo juez online en las metodologías de clase de programación puesto que permiten: motivar al estudiante, promover el interés en las temáticas a partir de la práctica y la competencia y mejorar el rendimiento académico. Estas integraciones en las metodologías de clase de programación han registrado a través de la literatura que sus efectos son positivos en lo que respecta a mejoramiento en rendimiento, habilidades, mejora en la lógica y la participación. Sin embargo, se evidencia una falta de estudios con el fin de determinar si la motivación, como factor de aprendizaje, se ve afectada por la intervención de herramientas de evaluación automática en las sesiones de clase. Es por esto que el presente artículo se centra en evaluar el impacto en la motivación por aprender de los estudiantes al usar una herramienta de evaluación automática de programas en la asignatura de programación de computadores. A partir de un diseño de investigación cuasiexperimental se comparó el nivel de motivación en el aprendizaje de los estudiantes del grupo experimental y de los estudiantes de un grupo control (estudiantes que cursaron la asignatura sin usar la herramienta de evaluación automática seleccionada) por medio de un pretest y postest con el instrumento MSLQ-Colombia. Adicionalmente, los estudiantes del grupo experimental respondieron una encuesta con preguntas de respuesta abierta que permitió recopilar las diferentes percepciones sobre la herramienta y la integración de este tipo de estrategias en la metodología de la clase. Los datos recolectados permitieron realizar un análisis estadístico respecto a la variación de la motivación en el aprendizaje de los grupos que participaron. Por un lado, los datos cuantitativos recopilados a través del MSLQ-Colombia no evidenciaron diferencias significativas en la motivación de los estudiantes del grupo experimental en el que se integró la herramienta de evaluación automática. Por otro lado, la información cualitativa permitió contrastar el impacto hallado en el análisis cuantitativo. Los datos de la encuesta de opinión de los estudiantes permitieron observar un aumento en los niveles de autoeficacia para el rendimiento de los estudiantes. Estos resultados permiten entender de mejor manera los efectos de la integración de herramientas de evaluación automática en la motivación por aprender de los estudiantes de programación de computadores. (Texto tomado de la fuente)', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/79756', 'unal/79756', 'Evaluación del efecto de la gamificación asistida por computador en la motivación de los estudiantes de programación de computadores', '2021', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/79756', 'estudiante:cuervo-cely-karen-daniela', 'Cuervo Cely, Karen Daniela', 'La enseñanza-aprendizaje de la Programación de Computadores conlleva desafíos que implican buscar nuevas metodologías de enseñanza en la que el estudiante se involucre activamente. Actualmente las metodologías relacionadas con el juego son ampliamente utilizadas por los efectos que pueden generar en aspectos como la motivación, participación, rendimiento académico y compromiso en los estudiantes. La gamificación está inmersa en dichas metodologías haciendo referencia al uso de elementos relacionados con el juego en contextos ajenos al juego. En el área de la Programación de Computadores se han realizado estudios que integran la gamificación asistida por computador en contextos académicos, con el objetivo de evidenciar los efectos reales que genera el uso de elementos relacionados con el juego en procesos formativos. Generalmente los resultados cualitativos evidencian efectos destacables en los diferentes aspectos analizados, sin embargo distintos estudios donde realizan análisis cuantitativos contradicen dichos hallazgos y exponen que integrar la gamificación no genera efectos estadísticamente significativos en aspectos evaluados como la motivación, participación, rendimiento académico, entre otros. La revisión de literatura analizada evidencia la necesidad de realizar más estudios empíricos en los que se integre la gamificación con el propósito de comprender y demostrar los efectos reales que genera en los distintos aspectos formativos. Por lo cual, esta investigación tiene como propósito encontrar el efecto que la gamificación asistida por computador genera en la motivación por aprender de los estudiantes de Programación de Computadores. Para tal fin, se diseñó y llevó a cabo un estudio cuasi-experimental en el que se integró una herramienta gamificada en la metodología de un curso de Introducción a la Programación de Computadores. A través de una revisión de literatura y un análisis comparativo se realizó la selección de CodeGym como el ambiente gamificado asistido por computador apto para la integración dentro de la metodología de la clase. A continuación, se estableció el diseño del estudio cuasi-experimental en el que se planteó la metodología de la intervención educativa y la aplicación de los instrumentos para medir el constructo motivacional por medio del cuestionario de auto-informe MSLQ-Colombia y una encuesta de percepciones dirigida a los estudiantes que participaron en el estudio. En este estudio participaron 48 estudiantes distribuidos en dos grupos de control y uno experimental, quienes fueron seleccionados mediante la técnica de muestreo no probabilístico por conveniencia. La información recolectada permitió realizar un análisis estadístico de la variación de la motivación en cada uno de los grupos participantes. La información cuantitativa obtenida mediante el MSLQ-Colombia permitió evidenciar que los estudiantes del grupo experimental en el que se integró el ambiente gamificado en la metodología de la clase, incrementaron significativamente los niveles relacionados con valoración de la tarea, atribuyendo un mayor grado de importancia, utilidad, gusto o interés hacia las temáticas expuestas en la asignatura. Los resultados reportados en esta investigación permiten comprender mejor los efectos, beneficios, y desafíos que brinda la integración de la gamificación asistida por computador en los procesos de enseñanza-aprendizaje de la programación de computadores. (Texto tomado de la fuente)', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/80862', 'unal/80862', 'Prototipo de herramienta computacional para el aprendizaje colaborativo de programación de computadores', '2021', 'maestria', 'Magíster en Ingeniería - Ingeniería de Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/80862', 'estudiante:mendez-lara-jhon-alexis', 'Mendez Lara, Jhon Alexis', 'El aprendizaje colaborativo asistido por computador CSCL (del inglés Computer Supported Collaborative Learning) es una propuesta educativa que busca que los estudiantes puedan alcanzar sus objetivos de aprendizaje a través de la interacción en grupo mediada por la tecnología. En el área de la programación de computadores, algunos estudios demuestran un aumento de la participación y mejores resultados en la resolución de problemas de programación por parte de los estudiantes que participan en ambientes de aprendizaje CSCL. En entornos universitarios, los cursos introductorios de programación de computadores buscan preparar a los estudiantes en la resolución de problemas a partir del uso de un lenguaje de programación; para ello, se han creado diferentes herramientas bajo el enfoque CSCL, las cuales sirven de espacios en donde los estudiantes autorregulan su aprendizaje, participan voluntariamente, discuten ideas y evalúan el trabajo de los demás. Sin embargo, según las implementaciones de software revisadas en la literatura, aún existe la necesidad de crear herramientas colaborativas no sólo en las etapas tempranas del proceso de resolución de problemas de programación, sino también durante el proceso de evaluación formativa de la resolución del problema mediante la colaboración de los compañeros. En este contexto, el objetivo de esta tesis es presentar la herramienta computacional denominada UNColab para apoyar la resolución de problemas de programación por medio de la colaboración entre estudiantes durante una etapa de evaluación por pares. Se realizó la implementación de un prototipo de UNColab, el cual fue probado durante la realización de una actividad de aprendizaje colaborativo en un curso de Programación de Computadores con 27 estudiantes de la Universidad Nacional de Colombia. Esta herramienta se desarrolló conforme a un guion de aprendizaje colaborativo, el cual permitió estructurar una dinámica de clase en dos actividades del curso; y la aplicación de la metodología de desarrollo orientada a prototipos, que facilitó la organización de cada una de las actividades de desarrollo de software. Los resultados de esta experiencia sugieren que los estudiantes perciben este tipo de herramientas como favorables en la enseñanza-aprendizaje de la programación de computadores. Además, sugirieron diferentes mejoras que podrían abrir las posibilidades a la realización de otros estudios. Por lo tanto, este trabajo contribuye al área de investigación por medio del desarrollo de una herramienta que permite apoyar la enseñanza de la programación de computadores en ambientes colaborativos. Asimismo, la validación de la herramienta en un curso de programación de computadores permite entender de una mejor manera los beneficios y retos que supone la utilización de herramientas para el aprendizaje colaborativo asistido por computador. (Texto tomado de la fuente).', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/76556', 'unal/76556', 'An information retrieval strategy for large multimodal data collections involving source code and natural language', '2019', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/76556', 'estudiante:baquero-vargas-juan-felipe', 'Baquero Vargas, Juan Felipe', 'Los repositorios de software almacenan datos sobre los productos de software, datos relacionados con la evolución de código fuente, requerimientos de software, reporte de bugs y comunicación entre desarrolladores. Los repositorios de software han crecido rápidamente en los últimos años y con ellos la necesidad de extraer información significativa de ellos. Un repositorio de software intersante es Stack Overflow(SO), este sitio web es uno de los sitios de Question Answering más grandes y usados por miles de desarrolladores de sofware en su día a día. En SO los desarrollares pueden preguntar cualquier duda relacionada con programación y software que será respondida por otros usuarios. Como SO, existen muchos repositorios de software con código fuente y texto con millones de ejemplares y la posibilidad de combinar ambas fuentes para extraer información de ellos que no es visible a simple vista. En este trabajo de tesis, exploramos como representar código fuente y lenguaje natural y cómo combinar estas representaciones. Intentamos resolver la tarea de entender como los usuarios de  SO  hablan  sobre  un  lenguage  de  programación,  que  tan  similares  son  los  lenguajes  de programación basados en cómo los usuarios hablen sobre ellos y, finalmente, proporcionar herramientas para construir una estrategia de recuperación de información para identificar post duplicados.', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/76549', 'unal/76549', 'Automatic source code analysis forassessment of solutions toprogramming tasks', '2019', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/76549', 'estudiante:rosales-castro-lina-fernanda', 'Rosales Castro, Lina Fernanda', 'Calificar  código  fuente  es  una  tarea  que  cada  instructor  de  programación  debe  enfrentaren su día a día. Esta tarea conlleva varios retos entre ellos la cantidad de código a calificar,la dificultad de la tarea propuesta, entender cómo cada estudiante está intentando resolverla  tarea  y  proveer  realimentación  para  garantizar  una  aprendizaje  de  calidad.  Esta  tarea no solo es relevante en contextos académicos, por ejemplo en la industria, calificar efectiva-mente código fuente es crucial en el proceso para contratar al programador adecuado para una vacante. En este trabajo, proponemos una modificación al proceso regular de calificar código agregando un componente automático (o por lo menos semi-automático) para ayudara un instructor de programación en esta tarea. Nuestra propuesta incluye una rúbrica para calificar código fuente, la construcción de un data set, la extracción y el análisis del código;para finalmente mostrar nuestra solución al problema de calificar código fuente de manera automática resolviendo la tarea como un problema de clasificación.', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/76553', 'unal/76553', 'Building a Developer’s Reputation Model for Programming Contest Platforms based on Source Code Analysis', '2019', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/76553', 'estudiante:garavito-mendez-oscar-javier', 'Garavito Mendez, Oscar Javier', 'Resumen: En los últimos años, los desarrolladores se han interesado en la programación competitiva, provocando una explosión en el uso de las plataformas en línea que diseñan este tipo de competencias. En ellas se resuelven una serie de problemas de programación. Este formato también ha resultado útil para fines de reclutamiento y capacitación. A medida que los desarrolladores participan en concursos, ganan puntos y se clasifican en rankings, de acuerdo con el rendimiento que tienen en cada competencia. Hoy en día puede decirse que estos rangos son análogos a los sistemas de reputación, ya que dan indicios acerca de la experiencia de los programadores. En esta tesis, se explora la relación entre esta reputación y las características del código fuente, extra ‘idas a través del análisis del código fuente, de las soluciones enviadas por los participantes. El objetivo de esta investigación es encontrar un conjunto de características, clasificadas en categorías léxicas, sintácticas, de calidad y legibilidad, que sean compartidas por los desarrolladores en el mismo nivel de conocimiento. Estas características nos permiten construir un modelo para predecir la experiencia de los programadores, considerándolos como principiantes o avanzados. En ese sentido, se diseñó un experimento para crear un modelo de clasificador, para llevar a cabo esa tarea. En general, los resultados lucen prometedores, logrando una precisión aproximada del 80 % y teniendo a las características léxicas como las más relevantes para el modelo.', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/76335', 'unal/76335', 'Static Analysis of Python Programs using Abstract Interpretation: An Application to Tensor Shape Analysis', '2019', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/76335', 'estudiante:cruz-camacho-elkin-alejandro', 'Cruz Camacho, Elkin Alejandro', 'Resumen: Los tensores, una extensión de los arrays, se usan de manera extensiva en una gran variedad de problemas en programación. Los tensores son los bloques básicos de construcción de múltiples frameworks de Aprendizaje de Máquina y son fundamentales en la definición de modelos de Aprendizaje Profundo. Los linters son herramientas indispensables para los programadores de hoy en día, ya que estos ayudan a los desarrolladores a revisar el código antes de ejecutarlo. Aunque los tensores son muy populares no existen tensores que revisen código con operaciones tensoriales. Dada la gran cantidad de trabajo hecho en Python con (y sin) tensores, es sorprendente el poco trabajo que se ha hecho en esta área.  La Interpretación Abstracta es una metodología/framework diseñada para analizar código de forma estática. La idea de Interpretación Abstracta es sobreaproximar de manera "sound" el resultado de ejecutar una pieza de código sobre todos las posibles entradas del programa.  Una sobreaproximación "sound" asegura que el Interprete Abstracto nunca omitirá un verdadero negativo, es decir, si una pieza de código no es señalada como incorrecta por el Interprete Abstracto entonces se puede asumir con seguridad que el código nunca fallará.  El Interprete Abstracto puede ser modificado para que sólo informe acerca de verdaderos positivos, aunque se pierda la propiedad de "soundness", es decir, el interprete sólo informa acerca de las partes de código que fallarán sin importar que suceda.    En este trabajo, formalizamos un subconjunto de Python con énfasis en operaciones con tensores. Nuestra formalización de la semántica de Python está basada en la Referencia oficial del Lenguage Python. Definimos un Interprete Abstracto y presentamos su implementación. Mostramos como cada parte del Interprete Abstracto fué definido: su Dominio Abstracto y semántica abstracta.    Presentamos la estructura de Pytropos, la implementación del Interprete Abstracto.  Pytropos es capaz de revisar las operaciones de arreglos de NumPy teniendo en cuenta broadcasting y algunas funciones complejas de NumPy como \texttt{array} y \texttt{dot}.  Construimos 74 casos de prueba unitaros, los cuales chequean la capacidad de Pytropos, además de 20 casos de prueba de propiedades, los cuales chequean que las reglas semánticas de Pytropos correspondan con la forma en la que Python es ejecutado. Mostramos las capacidades del Interprete Abstracto por medio de ejemplos de los test unitarios.', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/64771', 'unal/64771', 'Social engineering: psychology applied to Information Security', '2018', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/64771', 'estudiante:del-pozo-falconi-ivan-mauricio', 'Del Pozo Falconí, Iván Mauricio', '', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/60127', 'unal/60127', 'Prototipado automático de sistemas de información transaccionales usando una especificación en lenguaje natural restringido', '2017', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/60127', 'estudiante:alfonso-hoyos-jean-pierre', 'Alfonso Hoyos, Jean Pierre', 'Las actividades del ciclo de vida del desarrollo de software (o SDLC por sus siglas en ingl´es)  incluyen: an´alisis de requisitos, dise˜no de modelos, desarrollo, pruebas y mantenimiento. Las  tareas tempranas de este ciclo (an´alisis de requisitos y dise˜no) tienen un amplio impacto en  el ´exito del proyecto y por esto es fundamental que se lleven a cabo de una forma correcta.  Estas actividades por supuesto est´an incluidas en el proceso de desarrollo de sistemas de  informaci´on de procesamiento de transacciones. Estos sistemas de informaci´on son una de  las maneras de generar valor desde la informaci´on producida en una organizaci´on. Adem´as,  dan pie para generar sistemas de informaci´on de mayor complejidad y tambi´en permiten  mejorar los procesos de toma de decisiones en las organizaciones.  Sin embargo, los errores en las etapas tempranas del desarrollo de software son bastante  comunes. Estos errores pueden llevar a dificultades a nivel de presupuesto y calendario en  los proyectos de desarrollo de software, inclusive, a fracasos totales.  Por esta raz´on, en esta tesis se propone dise˜nar, desarrollar y evaluar una metodolog´ıa  para el prototipado autom´atico de sistemas de informaci´on transaccionales desde una especificaci´on  en lenguaje natural restringido. Lo cual busca mejorar los procesos de an´alisis de  requisitos y dise˜no de modelos puesto que permitir´ıa validar r´apidamente la funcionalidad  del software, y as´ı, facilitar la detecci´on de errores y por ende su correcci´on temprana durante  el desarrollo del proyecto.  Para esto, en esta tesis se propone una metodolog´ıa de prototipado r´apido basada en un  lenguaje natural restringido. Para crear este lenguaje natural restringido se usan como insumo  dos lenguajes de especificaci´on populares: BPMN (Business Process Modeling Notation)  y E-R (Entity - Relationship). Adem´as, para la generaci´on del prototipo funcional, se usar´an  t´ecnicas de generaci´on de c´odigo fuente guidas por la sintaxis de este lenguaje.  Como resultados de esta tesis, se llevaron a cabo dos implementaciones de la herramienta  de generaci´on de c´odigo fuente. Adem´as, se presentan tres casos de estudio que permiten  validar la aplicabilidad y efectividad de la metodolog´ıa propuesta: “Question cycle”, “Email  Voting” y “Odoo clone”.', 'repositorio_unal', '2026-07-31', 'yes');
INSERT INTO "theses" ("id", "handle", "title", "year", "degree", "degree_name_ri", "item_url", "student_id", "student_name", "abstract_es", "source", "harvested_at", "visible") VALUES ('tesis:unal/60068', 'unal/60068', 'Source code analysis on student assignments using machine learning techniques', '2017', 'maestria', 'Maestría en Ingeniería - Sistemas y Computación', 'https://repositorio.unal.edu.co/handle/unal/60068', 'estudiante:castellanos-morales-hugo-armando', 'Castellanos Morales, Hugo Armando', 'Para mejorar el éxito de los estudiantes en los cursos de programación, es importante entender  el proceso de aprendizaje y las dificultades comunes que enfrentan los estudiantes.  Aunque muchos estudios han investigado las posibles relaciones entre el rendimiento de los  estudiantes y aspectos de la auto-regulación del aprendizaje, poca atención se le ha dado  al código fuente producido por los estudiantes. El cual puede contener información valiosa  acerca de su proceso de aprendizaje. Esto es especialmente cierto en contextos donde las actividades  prácticas de programación son frecuentes y los estudiantes escriben código fuente  constantemente durante el desarrollo del curso.  Lo anterior, plantea las siguientes preguntas de investigación: ¿Cuál es la relación entre las  características del código fuente de los estudiantes y su rendimiento en un curso de programación  de computadores?. ¿Cuál es la relación entre las características del código fuente y  características de aprendizaje auto-regulado (motivación y estrategias de aprendizaje) en un  curso de programación de computadores?. ¿Cómo el código fuente y las características de  aprendizaje auto-regulado pueden predecir el rendimiento de los estudiantes?  Para responder estas preguntas, se presenta una estrategia para realizar el análisis de correlaciones  entre el rendimiento de los estudiantes, motivación, el uso de estrategias de aprendizaje,  y las métricas de código fuente en cursos de programación de computadores. Un  caso de estudio exhaustivo es presentado para evaluar la estrategia propuesta usando datos  recolectados de estudiantes. Además se usaba una herramienta de calificación automática  para evaluar las practicas, lo cual facilitaba la obtención de código fuente de estudiantes  para su análisis posterior. Las características de aprendizaje auto-regulado fueron obtenidas  usando el cuestionario: Motivated Strategies for Learning Questionnaire Colombia (MSLQColombia).  Los resultados muestran que las principales características del código fuente que están relacionadas  con el rendimiento de los estudiantes y características auto-reguladas son: las  métricas de longitud, que se correlaciona positivamente; y las medidas de complejidad de  Halstead, las cuales se correlacionan negativamente. Dados los resultados, es posible entender  mejor el código fuente de los estudiantes como un artefacto que puede ser usado para  monitorear características relacionadas con el aprendizaje auto-regulado, rendimiento en el  curso, y en general, su proceso de aprendizaje. De esta forma, investigaciones adicionales son  necesarias para verificar si dichas relaciones pueden dar a los educadores nuevas herramientas  para identificar y ayudar a estudiantes con problemas.', 'repositorio_unal', '2026-07-31', 'yes');
